fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // All vectors have the same length by assumption.
    // We create a new vector by iterating over indices,
    // selecting src[i] if mask[i] is true, else dst[i].
    let len = dst.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }

    result
}